import 'dart:math';

import 'package:flutter/material.dart';
import 'package:provider/provider.dart';

import '../../models/screen_config.dart';
import '../../services/playback_controller.dart';
import '../../theme/app_palette.dart';
import '../../theme/app_typography.dart';
import 'base_hero_container.dart';
import 'hero_title_block.dart';

/// Dot visualisation embedded in the Void hero slot: a single pulsing circle whose radius tracks the spectrum's bass energy (Void chrome owns transport). When [DotScreenConfig.showSongInfo] is true (B-020) the active track's Artist (H1) / Song (H2) overlay the top of the band in a [Stack] above the centered dot, using the shared [HeroTitleBlock] (B-046). The dot is clamped to a fraction of the smallest dimension so it never overflows.
class DotHero extends StatelessWidget {
  const DotHero({super.key, required this.config});

  final DotScreenConfig config;

  double _radiusFor(
    List<double> spectrum, {
    required double minRadius,
    required double maxRadius,
  }) {
    if (spectrum.isEmpty) return minRadius;

    var bass = 0.0;
    for (var i = 0; i < min(spectrum.length, 3); i++) {
      bass = max(bass, spectrum[i]);
    }

    final r =
        minRadius + bass * bass * config.sensitivity * (maxRadius - minRadius);
    return r.clamp(minRadius, maxRadius);
  }

  @override
  Widget build(BuildContext context) {
    final palette = Theme.of(context).extension<AppPalette>()!;
    // read (not watch): the dot animates off [spectrumListenable] below, so this
    // widget must NOT rebuild on every controller notify.
    final player = context.read<PlaybackController>();

    return LayoutBuilder(
      builder: (context, constraints) {
        final typography = Theme.of(context).extension<AppTypography>()!;

        // Clamp the dot so it always stays within the hero band.
        final minDim = min(constraints.maxWidth, constraints.maxHeight);
        final baseMaxRadius = minDim / 2;

        // When song-info is enabled, reserve enough top space so the dot never
        // intersects the (multi-line) artist/song block at normal + max text
        // size.
        final maxRadius = () {
          if (!config.showSongInfo) {
            return min(config.maxDotSize, baseMaxRadius);
          }

          const topPadding = 12.0;
          const titleDotGap = 8.0;
          const lineHeightMultiplier = 1.18; // keep in sync w/ heroHeadingStyle

          final h1Size = typography.heroSize * config.textScale;
          final h2Size = typography.heroSize * heroSongSizeFactor * config.textScale;

          // HeroTitleBlock reserves: (H1, 2 lines) + 8px spacer + (H2, 2 lines).
          final estimatedTitleHeight =
              2 * h1Size * lineHeightMultiplier +
              8 +
              2 * h2Size * lineHeightMultiplier;

          final reservedTop = topPadding + estimatedTitleHeight + titleDotGap;
          final verticalMaxRadius = constraints.maxHeight / 2 - reservedTop;

          return min(config.maxDotSize, min(baseMaxRadius, verticalMaxRadius));
        }();

        final minRadius = config.showSongInfo ? min(config.minDotSize, maxRadius) : config.minDotSize;

        return BaseHeroContainer(
          child: Stack(
            children: [
              // Pulsing dot — always centered. Only this subtree repaints per
              // spectrum frame (RepaintBoundary-isolated).
              Center(
                child: RepaintBoundary(
                  child: AnimatedBuilder(
                    animation: player.spectrumListenable,
                    builder: (context, _) {
                      final r = _radiusFor(
                        player.spectrumData,
                        minRadius: minRadius,
                        maxRadius: maxRadius.clamp(0.0, baseMaxRadius),
                      );
                      return Container(
                        width: r * 2,
                        height: r * 2,
                        decoration: BoxDecoration(
                          color: palette.fgPrimary
                              .withValues(alpha: config.dotOpacity),
                          shape: BoxShape.circle,
                        ),
                      );
                    },
                  ),
                ),
              ),
              // Optional song-info overlay pinned to the top of the hero band (B-020), above the dot.
              if (config.showSongInfo)
                Positioned(
                  left: 0,
                  right: 0,
                  top: 12,
                  child: Opacity(
                    opacity: config.textOpacity.clamp(0.0, 1.0),
                    child: HeroTitleBlock(textScale: config.textScale),
                  ),
                ),
            ],
          ),
        );
      },
    );
  }
}

